    ["Saved."] = "Salvo.",
    ["Search characters"] = "Pesquisar personagens",
    ["Short facts you write yourself, such as a name or a promise. The character knows them in every talk."] = "Fatos curtos que você mesmo escreve, como um nome ou uma promessa. O personagem os conhece em todas as conversas.",
    ["Short rules this character always follows when talking, for example: Never swear. Answer in one sentence."] = "Regras curtas que este personagem sempre segue ao falar, por exemplo: Nunca xingue. Responda em uma frase.",
